exercises.solution:
OPS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b,
}

def calculate(op, a, b):
    if op not in OPS:
        raise ValueError(f"неизвестная операция {op}")
    return OPS[op](a, b)

