exercises.solution:
def find_keys(data, key):
    found = []
    if isinstance(data, dict):
        if key in data:
            found.append(data[key])
        for value in data.values():
            found.extend(find_keys(value, key))
    elif isinstance(data, list):
        for item in data:
            found.extend(find_keys(item, key))
    return found

